-- BDIP: Synthetic BMI Bank Corn source model
-- All records generated by this project are synthetic.

CREATE TABLE IF NOT EXISTS raw_corn.branches (
    branch_id SMALLINT PRIMARY KEY,
    branch_code VARCHAR(20) NOT NULL UNIQUE,
    branch_name VARCHAR(100) NOT NULL,
    city VARCHAR(100) NOT NULL,
    is_active BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE IF NOT EXISTS raw_corn.customers (
    customer_id BIGINT PRIMARY KEY,
    customer_type VARCHAR(20) NOT NULL,
    first_name VARCHAR(100) NOT NULL,
    last_name VARCHAR(100) NOT NULL,
    date_of_birth DATE,
    customer_status VARCHAR(20) NOT NULL,
    branch_id SMALLINT REFERENCES raw_corn.branches(branch_id),
    created_at TIMESTAMPTZ NOT NULL,
    synthetic_record BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE IF NOT EXISTS raw_corn.accounts (
    account_id BIGINT PRIMARY KEY,
    customer_id BIGINT NOT NULL
        REFERENCES raw_corn.customers(customer_id),
    account_type VARCHAR(30) NOT NULL,
    currency CHAR(3) NOT NULL DEFAULT 'MRU',
    account_status VARCHAR(20) NOT NULL,
    opened_at TIMESTAMPTZ NOT NULL
);

CREATE TABLE IF NOT EXISTS raw_corn.transactions (
    transaction_id BIGINT PRIMARY KEY,
    account_id BIGINT NOT NULL
        REFERENCES raw_corn.accounts(account_id),
    branch_id SMALLINT REFERENCES raw_corn.branches(branch_id),
    transaction_type VARCHAR(30) NOT NULL,
    direction VARCHAR(10) NOT NULL,
    amount NUMERIC(18,2) NOT NULL,
    currency CHAR(3) NOT NULL DEFAULT 'MRU',
    transaction_status VARCHAR(20) NOT NULL,
    channel VARCHAR(30),
    transaction_timestamp TIMESTAMPTZ NOT NULL,
    synthetic_record BOOLEAN NOT NULL DEFAULT TRUE,
    CHECK (amount > 0),
    CHECK (direction IN ('credit', 'debit'))
);

CREATE TABLE IF NOT EXISTS raw_corn.transfers (
    transfer_id BIGINT PRIMARY KEY,
    transaction_id BIGINT NOT NULL UNIQUE
        REFERENCES raw_corn.transactions(transaction_id),
    recipient_bank VARCHAR(100),
    recipient_account_reference VARCHAR(100) NOT NULL,
    transfer_status VARCHAR(20) NOT NULL,
    initiated_at TIMESTAMPTZ NOT NULL,
    completed_at TIMESTAMPTZ
);

-- Indexes for joins and time-based analytics
CREATE INDEX IF NOT EXISTS idx_corn_customers_branch
    ON raw_corn.customers(branch_id);

CREATE INDEX IF NOT EXISTS idx_corn_accounts_customer
    ON raw_corn.accounts(customer_id);

CREATE INDEX IF NOT EXISTS idx_corn_transactions_account
    ON raw_corn.transactions(account_id);

CREATE INDEX IF NOT EXISTS idx_corn_transactions_timestamp
    ON raw_corn.transactions(transaction_timestamp);

CREATE INDEX IF NOT EXISTS idx_corn_transactions_type
    ON raw_corn.transactions(transaction_type);

CREATE INDEX IF NOT EXISTS idx_corn_transfers_transaction
    ON raw_corn.transfers(transaction_id);
